public class MemoryDemo {
    static java.util.List<Object> cache = new java.util.ArrayList<>();   // static: lives for the program's life

    static void leak() {
        cache.add(new Object());   // reachable via 'cache' forever — never eligible for GC
    }

    public static void main(String[] args) {
        for (int i = 0; i < 3; i++) {
            leak();
        }
        System.out.println(cache.size());   // 3 — every added object is still reachable
    }
}
